const fs = require('fs');
const path = require('path');
function write(filename, base64) {
  const filepath = path.join(__dirname, 'dist', filename);
  const dir = path.dirname(filepath);
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(filepath, Buffer.from(base64, 'base64'));
}
console.log('Criando arquivos na pasta dist...');
write('server.cjs', '');
write('index.html', '');
write('sw.js', '');
write('workbox-2fbc6a65.js', '');
write('assets/index-CsM5sScA.css', '');
write('assets/index-DzncONgE.js', '');
